/* Category metadata is eager; only visible illustrations are fetched. */
(()=>{'use strict';const catalog=MuseStickerCatalog,byId=new Map(catalog.items.map(s=>[s.id,s]));let category='nature',query='',limit=24,prefs={recent:[],favorites:[]},epoch=0,saveTimer;
const cacheKey=()=> 'muse-sticker-prefs:'+(window.MuseAccount?.id||'local');
function remember(){try{localStorage.setItem(cacheKey(),JSON.stringify(prefs))}catch{}clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{if(!window.MUSE_BETA)return;try{await window.MuseBeta.api('stickers/preferences','PUT',prefs)}catch(e){toast('스티커 목록을 서버에 저장하지 못했어요. 이 기기의 기록은 유지해요.')}},250)}
function draw(){let box=$('stickerGrid');if(!box)return;let rows=query?catalog.items.filter(s=>s.name.includes(query)||s.id.includes(query.toLowerCase())):category==='recent'?prefs.recent.map(id=>byId.get(id)).filter(Boolean):category==='favorites'?prefs.favorites.map(id=>byId.get(id)).filter(Boolean):catalog.items.filter(s=>s.category===category);$('stickerResultCount').textContent=(query?'검색 결과 · ':'')+rows.length+'종';box.innerHTML=rows.length?rows.slice(0,limit).map(s=>'<div class="sticker-choice"><button data-sticker-add="'+s.id+'" aria-label="'+s.name+' 스티커 추가"><img loading="lazy" decoding="async" src="/assets/stickers/'+s.id+'.svg" alt=""><span>'+s.name+'</span></button><button class="sticker-favorite" data-sticker-favorite="'+s.id+'" aria-label="'+s.name+' 즐겨찾기" aria-pressed="'+prefs.favorites.includes(s.id)+'">'+(prefs.favorites.includes(s.id)?'★':'☆')+'</button></div>').join(''):'<p class="sticker-empty">'+(category==='favorites'?'스티커 옆 별을 누르면 여기에 모여요.':category==='recent'?'보드에 붙인 스티커를 여기에 모아둘게요.':'찾는 스티커가 없어요.')+'</p>';$('stickerMore').hidden=rows.length<=limit;document.querySelectorAll('[data-sticker-category]').forEach(b=>b.classList.toggle('active',!query&&b.dataset.stickerCategory===category))}
async function open(){let mine=window.MuseAccount?.id;epoch++;const current=epoch;try{prefs={...prefs,...JSON.parse(localStorage.getItem(cacheKey())||'{}')}}catch{}openDialog('스티커','<label class="sticker-search">이름으로 찾기<input id="stickerSearch" type="search" placeholder="꽃, 카메라, 리본…" autocomplete="off"></label><div class="sticker-tabs" role="group" aria-label="스티커 카테고리">'+[{id:'recent',name:'최근 사용'},{id:'favorites',name:'즐겨찾기'},...catalog.groups].map(g=>'<button data-sticker-category="'+g.id+'">'+g.name+'</button>').join('')+'</div><small id="stickerResultCount" role="status"></small><div id="stickerGrid"></div><button id="stickerMore" hidden>더 보기</button><p class="sticker-credit">MUSE 오리지널 · 100종의 스크랩북 소품</p>',()=>{$('stickerSearch').oninput=e=>{query=e.target.value.trim();limit=24;draw()};$('stickerMore').onclick=()=>{limit+=24;draw()};document.querySelectorAll('[data-sticker-category]').forEach(b=>b.onclick=()=>{category=b.dataset.stickerCategory;query='';limit=24;$('stickerSearch').value='';draw()});draw()});if(window.MUSE_BETA)try{let remote=await window.MuseBeta.api('stickers/preferences');if(current!==epoch||mine!==window.MuseAccount?.id)return;prefs=remote;draw()}catch{}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let id=b.dataset.stickerFavorite||b.dataset.stickerAdd;if(!id||!byId.has(id))return;epoch++;if(b.dataset.stickerFavorite){prefs.favorites=prefs.favorites.filter(x=>byId.has(x));let i=prefs.favorites.indexOf(id);if(i<0)prefs.favorites.push(id);else prefs.favorites.splice(i,1);remember();draw()}else{add('sticker','muse-sticker:'+id,{shadow:false});prefs.recent=[id,...prefs.recent.filter(x=>x!==id)].slice(0,30);remember();$('dialog').close()}});
$('addSticker').onclick=()=>{query='';limit=24;open()};window.MuseStickers={url:content=>{let id=content?.startsWith('muse-sticker:')?content.slice(13):'';return byId.has(id)?'/assets/stickers/'+id+'.svg':null}};
})();
